  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for a retail customer by providing the target company, the number of shares, the payment amount, and a non-null allowance document.
   * The system creates the application only if the customer is currently eligible and has no approved application for the same company name.
   * Algorithm:
   * 1. Validate input:
   *    - company is not null
   *    - shares > 0
   *    - amount > 0
   *    - doc is not null
   * 2. Check isEligibleForIPO().
   * 3. Check whether an approved application already exists for the same company.name.
   * 4. If any validation or check fails, return false.
   * 5. Create a new Application with:
   *    - company = input company
   *    - customer = this customer
   *    - share = shares
   *    - amountOfMoney = amount
   *    - allowance = doc
   *    - status = PENDING
   * 6. Add the application to applications.
   * 7. Return true.
   * Related Features:
   * - applications
   * - canApplyForIPO
   * - createApplication(company, shares, amount, doc)
   * - isEligibleForIPO()
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO application.
   *   - Must be non-null.
   * - shares : int
   *   - Number of shares requested.
   *   - Must be greater than 0.
   * - amount : double
   *   - Payment amount offered for the application.
   *   - Must be greater than 0.
   * - doc : Document
   *   - Legal allowance document required for the application.
   *   - Must be non-null.
   * Output:
   * - boolean: true if the application record is created successfully; otherwise false.
   * Pre-condition:
   * - The customer exists and is a retail customer.
   * - The customer is eligible for IPO application at the time of creation.
   * - No approved application already exists for the same company name.
   * - Input parameters satisfy their validity constraints.
   * Post-condition:
   * - If return value is true, a new pending application is added to applications.
   * - The new application contains the provided company, shares, amount, and allowance document.
   * - If return value is false, no new application is added.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || shares <= 0 || amount <= 0 || doc == null || !isEligibleForIPO())
    {
      return false;
    }

    for (Application application : getApplications())
    {
      if (application != null
          && application.getStatus() == ApplicationStatus.APPROVAL
          && application.getCompany() != null
          && company.getName() != null
          && company.getName().equals(application.getCompany().getName()))
      {
        return false;
      }
    }

    Application application = IpoFactory.eINSTANCE.createApplication();
    application.setCompany(company);
    application.setCustomer(this);
    application.setShare(shares);
    application.setAmountOfMoney(amount);
    application.setAllowance(doc);
    application.setStatus(ApplicationStatus.PENDING);
    getApplications().add(application);
    return true;
    
  }

